<template>
 <view class="discovery-catalog">
  <view class="catalog-top"><button role="button" :class="{active:mode==='series'}" @click="mode='series'">产品系列</button><button role="button" :class="{active:mode==='texture'}" @click="mode='texture';category='cream'">质地选择</button><button role="button" @click="$emit('customize')">我的定制</button></view>
  <view v-if="error" class="catalog-message"><text>{{error}}</text><button role="button" @click="$emit('retry')">重新加载商品</button></view>
  <view v-else-if="loading&&!items.length" class="catalog-message">正在加载商城商品…</view>
  <view v-else class="catalog-body">
   <view class="catalog-sidebar"><button role="button" v-for="item in categories" :key="item.id" :class="{selected:category===item.id}" @click="category=item.id;mode='series'"><image :src="'/static/skincare/'+item.icon+'.svg'" mode="aspectFit"/><text>{{item.label}}</text></button></view>
   <scroll-view scroll-y class="catalog-content" :scroll-top="scrollTop">
    <view class="collection-cover"><image :src="category==='cream'?'/static/skincare/hero-creams.jpg':'/static/skincare/hero.jpg'" mode="aspectFill"/><view><text>HELUOJIA</text><text>{{category==='cream'?'三种润泽\n随心选择':'你的日常\n由你选择'}}</text></view></view>
    <view class="collection-heading"><text>{{mode==='texture'?'清润 · 中润 · 倍润':currentCategory.label+'系列'}}</text><text>{{shown.length}} 款</text></view>
    <text v-if="mode==='texture'" class="collection-note">按你喜欢的润泽感，认识三款面霜。</text>
    <view class="catalog-grid"><button role="button" class="catalog-product" v-for="product in shown" :key="product.id" @click="$emit('product',product)"><view class="catalog-photo"><image :src="asset(product.image,640)" mode="aspectFit"/><text v-if="product.spec" class="texture-tag">{{product.spec}}</text></view><text class="product-name">{{product.name}}</text><text class="product-price">¥ {{money(product.price)}}<text v-if="Number(product.stock)<=0">暂时缺货</text></text></button></view>
    <view v-if="!shown.length" class="catalog-message">这个分类暂时没有在售单品</view>
    <button role="button" class="full-mall" @click="$emit('mall')">进入原商城，查看全部商品 →</button>
   </scroll-view>
  </view>
 </view>
</template>
<script>
import {asset,money} from '../services/shop.js'
import {SKINCARE_CATEGORIES,skincareCatalog} from '../services/skincare-content.js'
export default {
 props:{products:{type:Array,default:()=>[]},loading:Boolean,error:String},emits:['product','customize','retry','mall'],
 data(){return{mode:'series',category:'water',categories:SKINCARE_CATEGORIES,scrollTop:0}},
 computed:{items(){return skincareCatalog(this.products)},currentCategory(){return this.categories.find(c=>c.id===this.category)||this.categories[0]},shown(){return this.items.filter(p=>this.currentCategory.codes.includes(p.product_code)&&(this.mode!=='texture'||['清润','中润','倍润'].includes(p.spec)))}},
 watch:{category(){this.scrollTop=1;this.$nextTick(()=>{this.scrollTop=0})},mode(){this.scrollTop=1;this.$nextTick(()=>{this.scrollTop=0})}},methods:{asset,money}
}
</script>
<style scoped>
.discovery-catalog{background:var(--shop-surface, #fdfeff);color:var(--shop-text, #2b424f)}.discovery-catalog button{font:inherit;line-height:1.5;border-radius:0;margin:0;padding:0;background:transparent;color:inherit}.discovery-catalog button:after{border:0}.catalog-top{height:50px;display:flex;align-items:center;justify-content:space-around;background:var(--shop-surface, #fdfeff)}.catalog-top button{padding:13px 8px;font-size:14px;color:#8a8e91;position:relative}.catalog-top button.active{color:var(--shop-text, #2b424f);font-weight:600}.catalog-top button.active:before{content:'';height:5px;position:absolute;left:9px;right:9px;bottom:12px;background:var(--shop-border, #d5e6ee);transform:rotate(-3deg)}.catalog-body{display:flex;height:calc(100vh - var(--skin-top) - 172px - env(safe-area-inset-bottom));min-height:430px}.catalog-sidebar{flex-shrink:0;width:76px;background:var(--shop-background, #f3f8fb)}.catalog-sidebar button{height:99px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:9px;font-size:12px;color:#9a9da0;width:100%}.catalog-sidebar image{width:28px;height:28px;opacity:.45}.catalog-sidebar .selected{background:var(--shop-surface, #fdfeff);color:#45494b}.catalog-sidebar .selected image{opacity:1}.catalog-content{flex:1;min-width:0;height:100%;box-sizing:border-box}.collection-cover{height:142px;position:relative;background:var(--shop-background, #f3f8fb);margin:13px 17px 22px;overflow:hidden}.collection-cover>image{position:absolute;right:-25px;top:-10px;width:72%;height:180px;mix-blend-mode:multiply}.collection-cover>view{position:relative;padding:23px 12px}.collection-cover text{display:block;font-size:9px;letter-spacing:.7px}.collection-cover text+text{font-size:18px;font-weight:600;line-height:1.5;margin-top:10px;white-space:pre-line;letter-spacing:0}.collection-heading{display:flex;justify-content:space-between;align-items:center;margin:0 17px 20px;gap:8px}.collection-heading>text:first-child{font-size:13px;border:1px solid #858b8e;padding:3px 12px;border-radius:20px;box-shadow:0 2px 0 #eceeef}.collection-heading>text:last-child{font-size:10px;color:#929a9e;white-space:nowrap}.collection-note{font-size:11px;color:#8b9397;display:block;margin:-7px 17px 18px}.catalog-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 14px;padding:0 17px}.catalog-product{text-align:left!important;width:100%;white-space:normal}.catalog-photo{aspect-ratio:1;background:var(--shop-background, #f3f8fb);position:relative;overflow:hidden;border-radius:3px}.catalog-photo image{height:100%;width:100%}.texture-tag{position:absolute;top:6px;right:6px;border-radius:9px 9px 0 9px;background:var(--shop-border, #d5e6ee);font-size:10px;padding:2px 6px}.product-name{display:block;font-size:13px;line-height:1.8;margin-top:12px;min-height:42px}.product-price{display:flex;flex-wrap:wrap;align-items:center;gap:5px;margin-top:5px;font-size:13px}.product-price>text{font-size:10px;color:#92999d}.full-mall{margin:35px 17px 25px!important;font-size:11px!important;color:#7c8d92!important;text-align:left}.catalog-message{padding:55px 20px;text-align:center;font-size:13px;color:#7c898e}.catalog-message>text{display:block}.catalog-message button{font-size:13px;background:var(--shop-soft, #eaf5fb);border-radius:22px;margin-top:20px;padding:10px 18px}.discovery-catalog button:focus-visible{outline:2px solid var(--shop-border, #d5e6ee);outline-offset:-2px}.discovery-catalog button:active{opacity:.7}@media(max-width:360px){.catalog-sidebar{width:65px}.catalog-grid{gap:18px 10px;padding:0 12px}.collection-cover{margin-left:12px;margin-right:12px;height:125px}.collection-cover text+text{font-size:16px}.collection-heading{margin-left:12px;margin-right:12px}.collection-heading>text:first-child{padding-left:8px;padding-right:8px;font-size:12px}}
</style>
